* Control Block for Measurements
.control
* 1. Operating Point Analysis
op
let v_vop = v(vop)
let v_vom = v(vom)
let diff_out_offset = v(vop) - v(vom)
let v_cm_out = (v(vop) + v(vom)) / 2
let v_vm = v(vm)
let v_vp = v(vp)
let i_vdd = -i(VDD)
let p_diss = i_vdd * 1.8

print diff_out_offset
print v_cm_out
print v_vop
print v_vom
print v_vm
print v_vp
print i_vdd
print p_diss

* 2. AC Frequency Response Analysis
ac dec 50 10k 10G
let diff_gain_db = vdb(vop, vom)
let phase_deg = 180/PI * cph(v(vop) - v(vom))
meas ac differential_dc_gain find diff_gain_db at=100k
meas ac unity_gain_frequency when diff_gain_db=0 fall=1

* 3. Transient Step Response Analysis (as in Fig. 26.44c,d & 26.45)
tran 50p 90n 0n
let vdiff = v(vop) - v(vom)
let vin_diff = v(vip) - v(vim)
meas tran vdiff_max max vdiff from=5n to=9n
meas tran vdiff_min min vdiff from=10n to=14n
meas tran settling_time trig vin_diff val=0 rise=1 targ vdiff val=0.2 rise=1

quit
.endc
.end

